-- F2.11 · Seed de datos dummy del schema guide.
-- Todos los uuids llevan el prefijo d0d0d0d0- para que guide_dummy_purge.sql los borre en F7.1.
-- Idempotente: on conflict do nothing. Sin usuarios en auth ni user_reviews. Los archivos de Storage no los crea este SQL
-- (D22: las 9 fotos dummy están en el bucket; ver el bloque final de guide.media y portadas). site_settings se deja con sus valores por defecto.
-- Ejecutar como postgres (SQL Editor o execute_sql).

begin;
-- F6.4: los triggers de guide.articles/article_items bloquean escribir o borrar lo vivo (PT423). Este script
-- de mantenimiento (solo como postgres, con bypassrls) lo declara explícitamente para su transacción.
select set_config('guide.draft_op', 'maintenance', true);
-- F6.9 (O1): las fichas shoe publicadas se insertan antes que su detalle (FK items → shoes); la comprobación de
-- marca/modelo se difiere al commit.
set constraints guide.items_shoe_require_brand_model deferred;

-- Helpers de sesión: bloques [["h2"|"p"|"quote", texto] | ["ul", [textos]]] → documento Tiptap y HTML coherente.
create or replace function pg_temp.esc(t text) returns text language sql immutable as $f$
  select replace(replace(replace(t, '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
$f$;
create or replace function pg_temp.txt(t text) returns jsonb language sql immutable as $f$
  select jsonb_build_array(jsonb_build_object('type', 'text', 'text', t))
$f$;
create or replace function pg_temp.tt(b jsonb) returns jsonb language sql immutable as $f$
  select jsonb_build_object('type', 'doc', 'content', coalesce(jsonb_agg(
    case e ->> 0
      when 'h2' then jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 2), 'content', pg_temp.txt(e ->> 1))
      when 'p' then jsonb_build_object('type', 'paragraph', 'content', pg_temp.txt(e ->> 1))
      when 'quote' then jsonb_build_object('type', 'blockquote', 'content',
        jsonb_build_array(jsonb_build_object('type', 'paragraph', 'content', pg_temp.txt(e ->> 1))))
      when 'ul' then jsonb_build_object('type', 'bulletList', 'content',
        (select jsonb_agg(jsonb_build_object('type', 'listItem', 'content',
           jsonb_build_array(jsonb_build_object('type', 'paragraph', 'content', pg_temp.txt(li #>> '{}')))) order by o)
         from jsonb_array_elements(e -> 1) with ordinality as l(li, o)))
    end order by n), '[]'::jsonb))
  from jsonb_array_elements(b) with ordinality as t(e, n)
$f$;
create or replace function pg_temp.th(b jsonb) returns text language sql immutable as $f$
  select coalesce(string_agg(
    case e ->> 0
      when 'h2' then '<h2>' || pg_temp.esc(e ->> 1) || '</h2>'
      when 'p' then '<p>' || pg_temp.esc(e ->> 1) || '</p>'
      when 'quote' then '<blockquote><p>' || pg_temp.esc(e ->> 1) || '</p></blockquote>'
      when 'ul' then '<ul>' || (select string_agg('<li><p>' || pg_temp.esc(li #>> '{}') || '</p></li>', '' order by o)
                                from jsonb_array_elements(e -> 1) with ordinality as l(li, o)) || '</ul>'
    end, '' order by n), '')
  from jsonb_array_elements(b) with ordinality as t(e, n)
$f$;

